import path from 'node:path';
import fs from 'node:fs';
import { fileURLToPath } from 'node:url';
import express from 'express';
import Database from 'better-sqlite3';

const here = path.dirname(fileURLToPath(import.meta.url));
const distDir = path.resolve(here, '../frontend/dist');
const PORT = Number(process.env.PORT) || 3000;
const DB_PATH = process.env.DATABASE_PATH || './data/todos.db';

fs.mkdirSync(path.dirname(path.resolve(DB_PATH)), { recursive: true });
const db = new Database(DB_PATH);
db.exec(`CREATE TABLE IF NOT EXISTS todos (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL
);`);

const toTodo = (r) => ({ id: r.id, title: r.title, completed: !!r.completed, createdAt: r.created_at });
const err = (res, status, code, message) => res.status(status).json({ error: { code, message } });
const bad = (message) => Object.assign(new Error(message), { status: 400, code: 'VALIDATION_ERROR' });

function checkTitle(t) {
  if (typeof t !== 'string') throw bad('title must be a string');
  const v = t.trim();
  if (v.length === 0) throw bad('title must not be empty');
  if ([...v].length > 200) throw bad('title must be at most 200 characters');
  return v;
}

const app = express();
const api = express.Router();
api.use(express.json());
api.use((req, res, next) => {
  if (['POST', 'PATCH'].includes(req.method) && (req.body === null || typeof req.body !== 'object' || Array.isArray(req.body)))
    return next(bad('body must be a JSON object'));
  next();
});

api.get('/todos', (req, res) => {
  res.json(db.prepare('SELECT * FROM todos ORDER BY created_at ASC, id ASC').all().map(toTodo));
});

api.post('/todos', (req, res) => {
  const title = checkTitle(req.body.title);
  const info = db.prepare('INSERT INTO todos (title, completed, created_at) VALUES (?, 0, ?)').run(title, new Date().toISOString());
  res.status(201).json(toTodo(db.prepare('SELECT * FROM todos WHERE id = ?').get(info.lastInsertRowid)));
});

const idCheck = (req, res, next) => {
  if (!/^[1-9]\d*$/.test(req.params.id)) return err(res, 404, 'NOT_FOUND', 'Todo not found');
  const row = db.prepare('SELECT * FROM todos WHERE id = ?').get(Number(req.params.id));
  if (!row) return err(res, 404, 'NOT_FOUND', 'Todo not found');
  req.row = row;
  next();
};

api.patch('/todos/:id', idCheck, (req, res) => {
  const b = req.body;
  const has = (k) => Object.prototype.hasOwnProperty.call(b, k);
  if (!has('title') && !has('completed')) throw bad('title or completed is required');
  let title = req.row.title, completed = req.row.completed;
  if (has('title')) title = checkTitle(b.title);
  if (has('completed')) {
    if (typeof b.completed !== 'boolean') throw bad('completed must be a boolean');
    completed = b.completed ? 1 : 0;
  }
  db.prepare('UPDATE todos SET title = ?, completed = ? WHERE id = ?').run(title, completed, req.row.id);
  res.json(toTodo(db.prepare('SELECT * FROM todos WHERE id = ?').get(req.row.id)));
});

api.delete('/todos/:id', idCheck, (req, res) => {
  db.prepare('DELETE FROM todos WHERE id = ?').run(req.row.id);
  res.status(204).end();
});

api.use((req, res) => err(res, 404, 'NOT_FOUND', 'Not found'));
api.use((e, req, res, next) => {
  if (e.status === 400 || e.type === 'entity.parse.failed' || e.type === 'entity.too.large')
    return err(res, 400, 'VALIDATION_ERROR', e.code === 'VALIDATION_ERROR' ? e.message : 'Invalid JSON body');
  console.error(e);
  err(res, 500, 'INTERNAL_ERROR', 'Internal server error');
});

app.use('/api', api);
app.use(express.static(distDir));
app.use((req, res) => res.sendFile(path.join(distDir, 'index.html')));

app.listen(PORT, () => console.log(`Server listening on http://localhost:${PORT}`));
EOF
