import { StrictMode, useState, useEffect, useRef } from 'react';
import { createRoot } from 'react-dom/client';
import '@fontsource/inter/400.css';
import '@fontsource/inter/500.css';
import '@fontsource/inter/600.css';
import '@fontsource/inter/700.css';
import './styles.css';

async function api(method, url, body) {
  let res;
  try {
    res = await fetch(url, {
      method,
      headers: body ? { 'Content-Type': 'application/json' } : undefined,
      body: body ? JSON.stringify(body) : undefined,
    });
  } catch {
    throw new Error('Network error. Please try again.');
  }
  if (res.status === 204) return null;
  let data;
  try { data = await res.json(); } catch {
    throw new Error(`Unexpected server response (${res.status})`);
  }
  if (!res.ok) throw new Error(data?.error?.message || `Request failed (${res.status})`);
  return data;
}

function validate(t) {
  const v = t.trim();
  if (!v) return 'Title must not be empty';
  if ([...v].length > 200) return 'Title must be at most 200 characters';
  return null;
}

function Row({ todo, editing, onEdit, onCancel, run, setError }) {
  const [text, setText] = useState(todo.title);
  const ref = useRef(null);
  useEffect(() => { if (editing) { setText(todo.title); ref.current?.focus(); } }, [editing]);
  const save = async (e) => {
    e.preventDefault();
    const v = validate(text);
    if (v) return setError(v);
    if (await run(() => api('PATCH', `/api/todos/${todo.id}`, { title: text.trim() }))) onCancel();
  };
  if (editing) {
    return (
      <li>
        <form className="row" onSubmit={save} onKeyDown={(e) => e.key === 'Escape' && onCancel()}>
          <input ref={ref} className="edit-input" aria-label="Edit title" value={text} onChange={(e) => setText(e.target.value)} />
          <button type="submit" className="btn primary">Save</button>
          <button type="button" className="btn" onClick={onCancel}>Cancel</button>
        </form>
      </li>
    );
  }
  return (
    <li className="row">
      <input type="checkbox" aria-label={`Toggle ${todo.title}`} checked={todo.completed}
        onChange={(e) => run(() => api('PATCH', `/api/todos/${todo.id}`, { completed: e.target.checked }))} />
      <span className={'title' + (todo.completed ? ' done' : '')}>{todo.title}</span>
      <div className="actions">
        <button type="button" className="btn edit" aria-label={`Edit ${todo.title}`} onClick={onEdit}>Edit</button>
        <button type="button" className="btn danger" aria-label={`Delete ${todo.title}`}
          onClick={() => run(() => api('DELETE', `/api/todos/${todo.id}`))}>Delete</button>
      </div>
    </li>
  );
}

function App() {
  const [todos, setTodos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [loadFailed, setLoadFailed] = useState(false);
  const [error, setError] = useState('');
  const [filter, setFilter] = useState('all');
  const [title, setTitle] = useState('');
  const [editId, setEditId] = useState(null);

  const load = async () => {
    setLoading(true);
    try {
      setTodos(await api('GET', '/api/todos'));
      setLoadFailed(false);
      setError('');
    } catch (e) {
      setLoadFailed(true);
      setError(e.message);
    }
    setLoading(false);
  };
  useEffect(() => { load(); }, []);

  // run a mutation, then resync from server; returns true on success
  const run = async (fn) => {
    try {
      await fn();
    } catch (e) {
      setError(e.message);
      try { setTodos(await api('GET', '/api/todos')); } catch { /* keep */ }
      return false;
    }
    try {
      setTodos(await api('GET', '/api/todos'));
      setError('');
    } catch (e) {
      setError(e.message);
      return false;
    }
    return true;
  };

  const add = async (e) => {
    e.preventDefault();
    const v = validate(title);
    if (v) return setError(v);
    if (await run(() => api('POST', '/api/todos', { title: title.trim() }))) setTitle('');
  };

  const visible = todos.filter((t) => filter === 'all' || (filter === 'active' ? !t.completed : t.completed));
  const left = todos.filter((t) => !t.completed).length;

  return (
    <main>
      <h1>Todos</h1>
      <div className="card">
        <form className="new" onSubmit={add}>
          <label htmlFor="new-todo" className="sr-only">New todo</label>
          <input id="new-todo" className="text" placeholder="What needs to be done?" value={title} onChange={(e) => setTitle(e.target.value)} />
          <button type="submit" className="add">Add</button>
        </form>
        {error && (
          <div role="alert" className="alert">
            {error}
            {loadFailed && <> <button type="button" className="btn" onClick={load}>Retry</button></>}
          </div>
        )}
        {loading ? (
          <p role="status" className="msg">Loading…</p>
        ) : loadFailed ? null : visible.length === 0 ? (
          <p className="msg">No todos</p>
        ) : (
          <ul aria-label="Todo list">
            {visible.map((t) => (
              <Row key={t.id} todo={t} editing={editId === t.id} onEdit={() => setEditId(t.id)}
                onCancel={() => setEditId(null)} run={run} setError={setError} />
            ))}
          </ul>
        )}
        <div className="footer">
          <span className="count">{left} {left === 1 ? 'item' : 'items'} left</span>
          <div className="filters">
            {[['all', 'All'], ['active', 'Active'], ['completed', 'Completed']].map(([k, l]) => (
              <button key={k} type="button" className="filter" aria-pressed={filter === k} onClick={() => setFilter(k)}>{l}</button>
            ))}
          </div>
        </div>
      </div>
    </main>
  );
}

createRoot(document.getElementById('root')).render(<StrictMode><App /></StrictMode>);
EOF
